    lines = self._body_lines()
    visible_height = self._visible_body_height()
    max_scroll = max(0, len(lines) - visible_height)
    position = (
        f"历史 {self._body_scroll + 1}-{min(len(lines), self._body_scroll + visible_height)}/{len(lines)}"
        if lines else "历史 0/0"
    )
    parts = [self._footer_hint, position]
    if extra:
        parts.append(extra)
    if self._follow_output and max_scroll > 0:
        parts.append("当前跟随最新输出")
