    tool_text.append("  ⚙ ", style=self._theme.accent)
    normalized_stage = (stage or "running").strip().lower()
    if normalized_stage == "planning":
        tool_text.append(
            f"{self._format_source_label(source)} Tool Preparing: ",
            style=self._theme.dim,
